recipes.code:
{
  "inputs": [
    {
      "id": "ddg-private-key",
      "type": "promptString",
      "description": "EVM (Base) wallet private key used to auto-pay x402 on paid routes (optional; free/free-trial routes need no wallet).",
      "password": true
    }
  ],
  "servers": {
    "ddg-agent-services": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "ddg-agent-services-mcp@0.5.0"
      ],
      "env": {
        "DDG_AGENT_ID": "<ddg-agent-id>",
        "DDG_PRIVATE_KEY": "${input:ddg-private-key}"
      }
    }
  }
}
